import subprocess, time, re, urllib.request, urllib.parse, os, sys, json, shutil, signal, sqlite3

PORT = 8308
BASE = 'http://127.0.0.1:%d' % PORT
ROOT = '/tmp/explore/drill-selection'
OUT = ROOT + '/out'
MASTER = '/tmp/explore/_example_master'
os.makedirs(OUT, exist_ok=True)


def fresh(name, src=MASTER):
    d = os.path.join(ROOT, name)
    shutil.rmtree(d, ignore_errors=True)
    shutil.copytree(src, d)
    return d


def mkcoll(name, decks):
    d = os.path.join(ROOT, name)
    shutil.rmtree(d, ignore_errors=True)
    os.makedirs(d)
    for k, v in decks.items():
        open(os.path.join(d, k + '.md'), 'w').write(v)
    return d


class Drill:
    def __init__(self, d, tag='t', args=(), wait=True):
        self.d = d
        self.tag = tag
        self.sop = OUT + '/' + tag + '.stdout'
        self.sep = OUT + '/' + tag + '.stderr'
        self.so = open(self.sop, 'wb')
        self.se = open(self.sep, 'wb')
        cmd = ['/workspace/executable', 'drill', d, '--port', str(PORT),
               '--open-browser', 'false'] + [str(a) for a in args]
        self.cmd = cmd
        self.p = subprocess.Popen(cmd, stdout=self.so, stderr=self.se, stdin=subprocess.DEVNULL)
        self.up = False
        self.rc = None
        if wait:
            for i in range(100):
                time.sleep(0.05)
                if self.p.poll() is not None:
                    self.rc = self.p.returncode
                    break
                try:
                    urllib.request.urlopen(BASE + '/', timeout=1).read()
                    self.up = True
                    break
                except Exception:
                    pass

    def get(self, path='/'):
        r = urllib.request.urlopen(BASE + path, timeout=5)
        return r.read().decode('utf-8', 'replace')

    def post(self, action, path='/'):
        data = urllib.parse.urlencode({'action': action}).encode()
        req = urllib.request.Request(BASE + path, data=data, method='POST')
        try:
            r = urllib.request.urlopen(req, timeout=5)
            return r.status, r.read().decode('utf-8', 'replace')
        except urllib.error.HTTPError as e:
            return e.code, e.read().decode('utf-8', 'replace')

    def stop(self, wait=3):
        if self.p.poll() is None:
            try:
                self.p.send_signal(signal.SIGINT)
            except Exception:
                pass
            try:
                self.p.wait(timeout=wait)
            except Exception:
                self.p.kill()
                self.p.wait()
        self.rc = self.p.returncode
        self.so.close()
        self.se.close()
        return self.rc

    def outs(self):
        return open(self.sop, 'rb').read(), open(self.sep, 'rb').read()


def strip(h):
    h = re.sub(r'<[^>]+>', ' ', h)
    h = (h.replace('&amp;', '&').replace('&lt;', '<').replace('&gt;', '>')
         .replace('&quot;', '"').replace('&#39;', "'").replace('&#x27;', "'"))
    return re.sub(r'\s+', ' ', h).strip()


def parse(html):
    o = {}
    m = re.search(r'<h1>(.*?)</h1>', html, re.S)
    o['deck'] = m.group(1) if m else None
    m = re.search(r'<div class="card-content">(.*?)</div>\s*</div>\s*</div>\s*<div class="controls"', html, re.S)
    o['content'] = strip(m.group(1)) if m else None
    if o['content'] is None:
        m = re.search(r'<div class="card-content">(.*?)<div class="controls"', html, re.S)
        o['content'] = strip(m.group(1)) if m else None
    m = re.search(r'class="progress-fill"[^>]*style="width:\s*([^"]*)"', html)
    o['w'] = m.group(1) if m else None
    o['btns'] = re.findall(r'name="action"\s+value="([^"]*)"', html)
    o['revealed'] = 'answer' in html and 'Reveal' not in o['btns']
    o['end'] = o['content'] is None
    o['key'] = (o['deck'], o['content'])
    return o


def seq(d, grade='Good', maxsteps=200, tag='t', args=(), keep_html=False, dr=None):
    if dr is None:
        dr = Drill(d, tag, args)
    res = []
    if not dr.up:
        return dr, None
    for i in range(maxsteps):
        h = dr.get('/')
        p = parse(h)
        if keep_html:
            p['html'] = h
        res.append(p)
        if p['end']:
            break
        g = grade(i, p) if callable(grade) else grade
        dr.post('Reveal')
        if g is None:
            break
        dr.post(g)
    return dr, res


def run(d, tag='t', args=(), grade='Good', maxsteps=200, keep=False):
    dr, res = seq(d, tag=tag, args=list(args), grade=grade, maxsteps=maxsteps, keep_html=keep)
    rc = dr.stop()
    return dr, res


def db(d):
    return sqlite3.connect(os.path.join(d, 'hashcards.db'))


def populate(d, tag='pop'):
    """Start+stop a drill so card rows are inserted, without reviewing."""
    dr = Drill(d, tag)
    if dr.up:
        dr.get('/')
    dr.stop()
    return dr


def schema(d):
    c = db(d)
    r = list(c.execute("select type,name,sql from sqlite_master"))
    c.close()
    return r


def dump(d, cols='card_hash,due_date,review_count'):
    c = db(d)
    r = list(c.execute('select %s from cards order by card_hash' % cols))
    c.close()
    return r


def label(res):
    """short label list of the card sequence"""
    out = []
    for p in res:
        if p['end']:
            out.append('<END>')
        else:
            out.append('%s|%s' % (p['deck'], (p['content'] or '')[:34]))
    return out
